async function carregarColaboradores(){if(!estaOnline()){colaboradores=lerLocal(COL_KEY,[]);preencherSelectColaboradores();renderizarColaboradores();return}const {data,error}=await db.from('xcmg_colaboradores').select('*').order('nome_exibicao',{ascending:true});if(error)throw error;colaboradores=data||[];gravarLocal(COL_KEY,colaboradores);preencherSelectColaboradores();renderizarColaboradores()}
