function limparForm(){editando=null;fotoAtual={url:'',path:''};removerFotoAtual=false;['nome','matricula','funcaoColaborador','area','funcao','inicio','fim','cid','descricao','observacao'].forEach(id=>$(id).value='');$('foto').value='';$('categoriaMotivo').value='';$('motivo').value='';$('tipo').value='Outras justificativas';atualizarListaMotivos();$('local').value='';$('atestadoFisico').value='N/A';$('enviadoGrupo').value='N/A';mostrarFoto('');$('btnSalvar').textContent='Adicionar registro';$('btnCancelar').classList.add('hidden');$('formTitle').textContent='Adicionar ocorrência'}

async function carregarNuvem(silencioso=false){if(carregando)return;if(!estaOnline()){carregarCacheOffline();return}carregando=true;if(!silencioso)statusNuvem('Sincronizando...');try{const [{data:regs,error:er},{data:cfg,error:ec},{data:cols,error:ecl}]=await Promise.all([db.from('xcmg_registros').select('*').order('created_at',{ascending:true}),db.from('xcmg_config').select('*').eq('id',1).maybeSingle(),db.from('xcmg_colaboradores').select('*').order('nome_exibicao',{ascending:true})]);if(er)throw er;if(ec)throw ec;if(ecl)throw ecl;registros=(regs||[]).map(r=>({id:r.id,tipo:r.tipo,categoria:r.categoria||'',motivo:r.motivo||'',nome:r.nome,nome_completo:r.nome_completo||'',matricula:r.matricula||'',funcao_colaborador:r.funcao_colaborador||'',area:r.area||'',funcao:r.funcao||'',local:r.local||'',inicio:r.inicio||'',fim:r.fim||'',cid:r.cid||'',descricao:r.descricao||'',atestado_fisico:r.atestado_fisico||'N/A',enviado_grupo:r.enviado_grupo||'N/A',observacao:r.observacao||'',foto_url:r.foto_url||'',foto_path:r.foto_path||'',created_at:r.created_at||''}));colaboradores=cols||[];config=cfg?{turma:cfg.turma,efetivoTotal:cfg.efetivo_total,nomeSistema:cfg.nome_sistema,desenvolvedor:cfg.desenvolvedor,estiloSimbolos:cfg.estilo_simbolos}:{...PADRAO};if(Array.isArray(cfg?.categorias_rh)&&cfg.categorias_rh.length){categoriasRH=cfg.categorias_rh;normalizarCategoriasRH();localStorage.setItem(CATEGORIAS_KEY,JSON.stringify(categoriasRH));atualizarSelectCategorias();renderizarGestaoCategorias()}await migrarDadosLocaisSeNecessario();carregarConfig();salvarCacheLocal();atualizarTudo();statusNuvem('Sincronizado')}catch(e){console.error(e);carregarCacheOffline();if(!silencioso&&estaOnline())console.warn('A nuvem não respondeu. Dados locais carregados.')}finally{carregando=false}}
async function migrarDadosLocaisSeNecessario(){if(localStorage.getItem(MIG_KEY)==='1')return;const locais=lerLocal(REG_KEY,[]),cfgLocal=lerLocal(CFG_KEY,null);if(registros.length===0&&Array.isArray(locais)&&locais.length){const payload=locais.map(r=>({tipo:r.tipo,categoria:r.categoria||'',motivo:r.motivo||'',nome:r.nome,nome_completo:r.nome_completo||r.nome||'',matricula:r.matricula||'',funcao_colaborador:r.funcao_colaborador||'',area:r.area||'',funcao:r.funcao||'',local:r.local||'',inicio:r.inicio||null,fim:r.fim||null,cid:r.cid||'',descricao:r.descricao||'',atestado_fisico:r.atestado_fisico||'N/A',enviado_grupo:r.enviado_grupo||'N/A',observacao:r.observacao||'',foto_url:r.foto_url||'',foto_path:r.foto_path||''}));const {error}=await db.from('xcmg_registros').insert(payload);if(error)throw error}if(cfgLocal){const {error}=await db.from('xcmg_config').upsert({id:1,turma:cfgLocal.turma||PADRAO.turma,efetivo_total:Number(cfgLocal.efetivoTotal||0),nome_sistema:cfgLocal.nomeSistema||PADRAO.nomeSistema,desenvolvedor:cfgLocal.desenvolvedor||PADRAO.desenvolvedor,estilo_simbolos:cfgLocal.estiloSimbolos||PADRAO.estiloSimbolos});if(error)throw error}localStorage.setItem(MIG_KEY,'1');if((locais&&locais.length)||cfgLocal){const {data:regs}=await db.from('xcmg_registros').select('*').order('created_at',{ascending:true});const {data:cfg}=await db.from('xcmg_config').select('*').eq('id',1).maybeSingle();registros=(regs||[]).map(r=>({id:r.id,tipo:r.tipo,categoria:r.categoria||'',motivo:r.motivo||'',nome:r.nome,nome_completo:r.nome_completo||'',matricula:r.matricula||'',funcao_colaborador:r.funcao_colaborador||'',area:r.area||'',funcao:r.funcao||'',local:r.local||'',inicio:r.inicio||'',fim:r.fim||'',cid:r.cid||'',descricao:r.descricao||'',atestado_fisico:r.atestado_fisico||'N/A',enviado_grupo:r.enviado_grupo||'N/A',observacao:r.observacao||'',foto_url:r.foto_url||'',foto_path:r.foto_path||'',created_at:r.created_at||''}));if(cfg)config={turma:cfg.turma,efetivoTotal:cfg.efetivo_total,nomeSistema:cfg.nome_sistema,desenvolvedor:cfg.desenvolvedor,estiloSimbolos:cfg.estilo_simbolos}}}
